<?php get_header(); $author = get_queried_object(); ?>
<header class="page-hero"><div class="wrap"><p class="eyebrow"><?php esc_html_e('Travel Riddle contributor', 'travel-riddle'); ?></p><h1><?php echo esc_html($author->display_name); ?></h1><?php if (!empty($author->description)) : ?><p class="hero__lede"><?php echo esc_html($author->description); ?></p><?php endif; ?></div></header>
<section class="section"><div class="wrap"><div class="section-head"><h2><?php esc_html_e('Stories by this author', 'travel-riddle'); ?></h2></div><div class="post-list"><?php while (have_posts()) : the_post(); ?><article><a href="<?php the_permalink(); ?>"><?php if (has_post_thumbnail()) { the_post_thumbnail('travel-riddle-card'); } ?></a><div class="post-list__body"><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(travel_riddle_excerpt()); ?></p></div></article><?php endwhile; the_posts_pagination(); ?></div></div></section>
<?php get_footer(); ?>
